function selectPractice(mode){view='select';root.innerHTML='<button class="academy-back" data-action="home">✨ Academia</button><div class="academy-hero"><h2>'+(mode==='daily'?'🌞 Misión del día':'🧠 Entrenamiento adaptativo')+'</h2><p>Selecciona tu grado para ajustar las preguntas a tu nivel.</p></div><div class="academy-grid">'+Array.from({length:11},function(_,i){var g=i+1;return '<button class="academy-tile" data-grade="'+g+'"><span>'+(['🐣','🐱','🐶','🦊','🐼','🦁','🐯','🐸','🦄','🚀','🏆'][i])+'</span><b>'+g+'.º grado</b><small>'+(g<=3?'Operaciones fundamentales':g<=6?'Multiplicación, fracciones y medidas':g<=8?'Decimales, porcentajes y álgebra':'Álgebra, potencias y funciones')+'</small></button>'}).join('')+'</div>';root.querySelectorAll('[data-grade]').forEach(function(b){b.addEventListener('click',function(){startPractice(Number(b.dataset.grade),mode)})})}
function renderPractice(){view='practice';var q=session.questions[session.pos];root.innerHTML='<button class="academy-back" data-action="home">✨ Academia</button><div class="academy-hero"><span class="academy-kicker">ENTRENAMIENTO INTELIGENTE</span><h2>Grado '+session.grade+' · '+(session.mode==='daily'?'Misión diaria':session.mode==='words'?'Problemas de la vida real':session.mode==='speed'?'Reto relámpago':session.mode==='exam'?'Examen simulacro':'Práctica adaptativa')+'</h2><p>Pregunta '+(session.pos+1)+' de '+session.questions.length+' · '+session.score+' aciertos</p><div class="academy-meter"><i style="width:'+(session.pos/session.questions.length*100)+'%"></i></div></div><div class="academy-panel"><div class="academy-question">'+esc(q.text)+'</div><div class="academy-options">'+q.options.map(function(v){return '<button class="academy-option" data-answer="'+esc(v)+'">'+esc(v)+'</button>'}).join('')+'</div><p id="academyFeedback" class="academy-feedback" aria-live="polite"></p><button id="academyHint" data-action="hint" class="academy-secondary">💡 Dame una pista</button><button id="academyNext" class="academy-primary" style="display:none">Siguiente ➜</button></div><p id="academySaveState" class="academy-save">💾 Guardado automático</p>';if(session.answered){var fb=document.getElementById('academyFeedback');fb.innerHTML='Ya respondiste esta pregunta. La respuesta correcta es <b>'+esc(q.answer)+'</b>.';root.querySelectorAll('.academy-option').forEach(function(b){b.disabled=true;if(b.dataset.answer===q.answer)b.classList.add('is-right')});document.getElementById('academyHint').style.display=session.mode==='exam'?'none':'inline-block';document.getElementById('academyNext').style.display='inline-block';document.getElementById('academyNext').textContent=session.pos===session.questions.length-1?'Ver resultado 🏁':'Siguiente ➜'}}
function answer(v){if(!session||session.answered)return;session.answered=true;var q=session.questions[session.pos],ok=String(v)===q.answer,fb=document.getElementById('academyFeedback');if(ok){session.score++;session.streak++;state.streak=(state.streak||0)+1;award(10+Math.min(10,session.streak*2),2)}else{session.streak=0;state.streak=0;state.total++;state.history.unshift({date:day(),xp:0,coins:0});state.history=state.history.slice(0,60);save()}if(session.mode==='daily')markDaily();if(session.mode==='words'&&ok&&session.score>=8&&state.badges.indexOf('palabra-experta')<0)state.badges.push('palabra-experta');if(session.mode==='speed'&&session.score>=12&&state.badges.indexOf('speed-demon')<0)state.badges.push('speed-demon');state.currentSession=session;save();fb.innerHTML=ok?'✅ ¡Muy bien! Ganaste XP y monedas.':'❌ La respuesta correcta es <b>'+esc(q.answer)+'</b>. ¡Aprender del error también cuenta!';root.querySelectorAll('.academy-option').forEach(function(b){b.disabled=true;if(b.dataset.answer===q.answer)b.classList.add('is-right');else if(b.dataset.answer===String(v))b.classList.add('is-wrong')});var next=document.getElementById('academyNext');next.style.display='inline-block';next.textContent=session.pos===session.questions.length-1?'Ver resultado 🏁':'Siguiente ➜'}
